    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xDFDF9EB25DFCDC25ULL + 0x827286CD3D8DA11EULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xBAE5C5516A4A89B5ULL + 0xAE6832FB0D5F7C40ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0xFC635521BE877835ULL + 0x9C9C8822682C03FEULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xDB9A89E1F7C859F5ULL + 0xA974D52AD82F2FE8ULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0xC375D570B6EB4DCFULL + 0x8A3F333280558EA3ULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0xCEBFF5727A915141ULL + 0xE0D2AE4C919BF3D3ULL);
    const std::uint64_t aNonceWordG = TwistMix64::DiffuseC(pNonce * 0xB5F3B3A5AD8856FDULL + 0x87B1B532E8F5BE21ULL);
    const std::uint64_t aNonceWordH = TwistMix64::DiffuseB(pNonce * 0xE1312977A4E4A0D5ULL + 0xE12991416FF72E2DULL);
