            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 1997U)) & S_BLOCK1], 39U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 2119U)) & S_BLOCK1], 27U));
