            aWandererK = aWandererK ^ ((RotL64(aIngress, 10U) + aOrbiterC) + RotL64(aOrbiterB, 24U));
            aWandererD = aWandererD + ((RotL64(aScatter, 57U) + aOrbiterF) + RotL64(aOrbiterC, 13U));
            aWandererG = aWandererG ^ ((((RotL64(aPrevious, 5U) + aOrbiterB) + RotL64(aOrbiterA, 39U)) + aNonceWordB) + aWUSaltG[((aIndex + 46U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aCross, 23U) + aOrbiterH) + RotL64(aOrbiterG, 35U));
